edits.oldText:
export function phoneLabel(phone: string) {
  if (phone.trim().length === 0) {
    return "Missing";
  }
  return phone.trim();
}

edits.newText:
export function phoneLabel(phone: string) {
  if (phone.trim().length === 0) {
    return "No phone";
  }
  return phone.trim();
}
